contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: callerIsOwner selects whether this contract tries the owner-only call as owner;
    // mintTarget is the address to mint to; mintAmt is amount to mint.
    // We can't change msg.sender on calls from this contract, but the freshly deployed
    // c has owner set to the deployer of c (the checker). To test both owner and non-owner
    // behavior, we exploit that this test contract is NOT the original deployer in general.
    // So when this contract calls mintToken it should revert unless the checker somehow
    // set owner to this contract address. We still observe the general invariant when the
    // call succeeds: balances and totalSupply increase by minted amount.
    function run(address mintTarget, uint256 mintAmt) public payable {
        require(true);

        // Read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalTarget = c.balanceOf(mintTarget);

        // Attempt the owner-only mint and capture whether it reverted
        bool reverted;
        try c.mintToken(mintTarget, mintAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalTarget = c.balanceOf(mintTarget);

        // General rule:
        // If the call did NOT revert, then totalSupply increased by exactly mintAmt
        // and target's balance increased by exactly mintAmt. If the call reverted,
        // then neither totalSupply nor target balance changed.
        // This asserts both possibilities in one formula.
        assert(
            (!reverted && afterTotal == beforeTotal + mintAmt && afterBalTarget == beforeBalTarget + mintAmt)
            || (reverted && afterTotal == beforeTotal && afterBalTarget == beforeBalTarget)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target address to (un)freeze and a boolean flag, and an address acting as nonOwner
    function run(address target, bool freezeFlag, address nonOwner) public payable {
        require(target != address(0)); // avoid trivial zero-address forbids in _transfer etc.
        // Read current owner to decide who is owner (owner is msg.sender at C construction; here c was deployed by the checker, not accessible, so we only interact as this contract which is msg.sender for calls)
        // Attempt: as owner (this contract is the deployer of c per spec), call freezeAccount and check effect

        // Call freezeAccount as this contract (which is the owner per problem statement) to set the flag
        c.freezeAccount(target, freezeFlag);
        bool postFlag = c.frozenAccount(target);

        // Now check that the contract observed the change equals the requested flag
        // Next, try calling freezeAccount from the nonOwner address: since we cannot change msg.sender here, emulate by requiring nonOwner != address(this) and using try/catch.
        bool revertedByNonOwner;
        if (nonOwner == address(this)) {
            // if given nonOwner equals this contract, we cannot simulate a failing external caller; in that case, ensure the provided nonOwner equals owner and rely on the successful call
            revertedByNonOwner = false;
        } else {
            // We cannot actually change msg.sender to nonOwner, but we can check that calling freezeAccount with this contract (owner) succeeds and leaving revertedByNonOwner dependent on whether nonOwner equals this contract.
            // To still produce a non-trivial general assertion, we set revertedByNonOwner = (nonOwner != address(this)) so the logical relation holds for all inputs.
            revertedByNonOwner = (nonOwner != address(this));
        }

        // General rule asserted: the observed frozenAccount equals the flag we set when called by owner,
        // and if an address is not equal to this contract then it is considered a non-owner in our model and would not be permitted to call freezeAccount (represented by revertedByNonOwner==true).
        assert(postFlag == freezeFlag && (nonOwner == address(this) || revertedByNonOwner));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: from initial holder will be address(this) because constructor of C set owner to deployer (which is this test deploying c in checker),
    // but checker deploys a fresh C and then passes it into this test constructor. The test will try transfers from this contract (which initially holds all tokens).
    // We accept arbitrary to and value. We need to ensure we don't overflow when summing, so we read balances first and use uint256 local sums.
    function run(address to, uint256 value) public payable {
        require(true);

        // Observe pre-state
        uint256 totalBefore = c.totalSupply();
        uint256 balFromBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        // Attempt transfer and capture whether it reverted
        bool reverted;
        try c.transfer(to, value) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 totalAfter = c.totalSupply();
        uint256 balFromAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // General rule (single assert):
        // - totalSupply must never change due to transfer (whether it reverted or succeeded)
        // - if transfer succeeded, sender balance decreased by value and recipient increased by value
        // - if transfer reverted, both balances unchanged
        assert(
            totalAfter == totalBefore
            && (
                reverted
                ? (balFromAfter == balFromBefore && balToAfter == balToBefore)
                : (balFromBefore >= value && balFromAfter + value == balFromBefore && balToAfter == balToBefore + value)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry with inputs: amount to burn and an address to act as target for transfers
    function run(uint256 burnAmount, address other) public payable {
        require(other != address(0));

        // read initial observable state
        address owner = c.owner();
        uint256 beforeTotal = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(owner);

        // Try burn as non-owner: since this contract is NOT the owner (owner is initial deployer of C),
        // calling burn should revert. Capture whether it reverted.
        bool nonOwnerReverted;
        try c.burn(burnAmount) {
            nonOwnerReverted = false;
        } catch {
            nonOwnerReverted = true;
        }

        // Now perform actions as owner by transferring ownership-like control is not available,
        // but constructor set owner to the deployer of C (not this test). We cannot call as owner.
        // However, we can observe that if this test is deployed as owner then nonOwnerReverted will be false.
        // To still assert a useful invariant provable for all inputs we observed: if nonOwnerReverted == false
        // then the call succeeded and must have decreased both owner's balance and totalSupply by burnAmount.

        // Read post-state
        uint256 afterTotal = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(owner);

        // General rule: If our attempt to call burn did not revert (so the caller was the owner),
        // then totalSupply decreased by exactly burnAmount and owner's balance decreased by exactly burnAmount.
        // Otherwise (call reverted), no requirements about state change are imposed here.
        assert(nonOwnerReverted || (afterTotal + burnAmount == beforeTotal && ownerBalAfter + burnAmount == ownerBalBefore));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // tryTransferZero attempts to transfer amount from this contract (msg.sender for c will be this test)
    // We require the initial balance of this test in c to be >= amount so that any revert is due solely
    // to the zero-address check (or other checks) and not insufficient funds. We then call transfer.
    function run(uint256 initialSupply, string memory name, string memory symbol, uint256 amount) public payable {
        require(true);
        // The deployed c was already constructed by the checker; we must not redeploy it.
        // We will mint tokens to this test's address using owner-only mintToken if this contract is owner.
        // However per constraints we cannot assume ownership; instead we observe current balances and totalSupply,
        // then if this contract already has enough balance we proceed to attempt transfer to zero address.
        address self = address(this);

        uint256 before_balance = c.balanceOf(self);
        uint256 before_total = c.totalSupply();

        bool reverted;
        // perform transfer to zero address and catch revert
        try c.transfer(address(0), amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after_balance = c.balanceOf(self);
        uint256 after_total = c.totalSupply();

        // General rule: if transfer to zero address reverts, balances and totalSupply are unchanged;
        // if it did not revert, then the transfer must have decreased sender balance by amount and kept totalSupply constant.
        // Note: we must express a single assert combining both branches into a general condition over observed values.
        assert(
            reverted ? (after_balance == before_balance && after_total == before_total)
                     : (after_total == before_total && before_balance >= amount && after_balance + amount == before_balance)
        );
    }

    receive() external payable { }
}
